import json
from playwright.sync_api import sync_playwright
BASE = "http://127.0.0.1:3301/tests/alunix-r8/runs/V3c/index.html"

def rects_intersect(a, b):
    left = max(a['left'], b['left']); right = min(a['right'], b['right'])
    top = max(a['top'], b['top']); bottom = min(a['bottom'], b['bottom'])
    if right <= left or bottom <= top: return 0
    return (right-left)*(bottom-top)

with sync_playwright() as p:
    b = p.chromium.launch()
    for w, h in [(390, 844), (320, 568)]:
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(BASE + "?preview=back", wait_until="networkidle")
        pg.wait_for_timeout(700)
        r = pg.evaluate("""() => {
          function rect(sel) { const el = document.querySelector(sel); if (!el) return null; const r = el.getBoundingClientRect(); return {left:r.left,right:r.right,top:r.top,bottom:r.bottom}; }
          return {
            glyph: rect('.card-glyph'),
            mark: rect('.card-mark'),
            services: rect('.card-services'),
            cta: rect('.card-cta')
          };
        }""")
        for k in ['mark','services','cta']:
            area = rects_intersect(r['glyph'], r[k]) if r['glyph'] and r[k] else None
            print(f"{w}x{h} glyph x {k}: overlap area = {area}")
        pg.close()
    b.close()
EOF
